def resolve(path, cwd, links):
    # Track number of links followed
    link_count = [0]

    # Normalize the initial path
    if not path.startswith('/'):
        path = cwd + '/' + path

    # Split path into components
    components = path.split('/')

    # Start resolution
    current = ''

    for component in components:
        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            # Move to parent directory
            if current == '':
                current = '/'
            else:
                # Remove last component
                last_slash = current.rfind('/')
                if last_slash == 0:
                    current = '/'
                else:
                    current = current[:last_slash]
            continue

        # Append the component
        if current == '':
            current = '/' + component
        elif current == '/':
            current = '/' + component
        else:
            current = current + '/' + component

        # Check if current path is a symlink
        if current in links:
            link_count[0] += 1
            if link_count[0] > 8:
                return None

            target = links[current]

            # Resolve the target relative to the directory containing the link
            if not target.startswith('/'):
                # Target is relative to the directory containing the link
                link_dir = current[:current.rfind('/')]
                if link_dir == '':
                    link_dir = '/'
                target = link_dir + '/' + target

            # Recursively resolve the target
            # We need to continue with remaining components after the target
            result = resolve(target, cwd, links)
            if result is None:
                return None
            current = result

    # Ensure no trailing slash except for '/'
    if current == '':
        return '/'

    return current

